SELECT p.gender, CASE WHEN p.gender = 'F' THEN CASE WHEN p.age BETWEEN 78 AND 88 THEN CASE WHEN e.drug_type = 'unique' THEN 1 WHEN e.drug_type = 'high_risk' THEN 2 WHEN e.route IS NOT NULL THEN 3 END ELSE 0 END AS medication_complexity_score, COUNT(DISTINCT a.hadm_id) AS num_admissions, COUNT(DISTINCT CASE WHEN a.dod IS NOT NULL THEN a.hadm_id END) AS num_deaths, AVG(a.los) AS avg_length_of_stay, SUM(CASE WHEN a.dod IS NOT NULL THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(DISTINCT a.hadm_id), 0) AS mortality_rate, SUM(CASE WHEN i.seq_num IS NOT NULL AND i.chartdate BETWEEN a.intime AND a.outtime THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(DISTINCT a.hadm_id), 0) AS readmission_rate FROM patients p JOIN admissions a ON p.subject_id = a.subject_id LEFT JOIN emar e ON a.hadm_id = e.hadm_id LEFT JOIN icustays i ON a.stay_id = i.stay_id WHERE p.age = 83 AND p.gender = 'F' AND a.admittime > '2015-01-01' AND a.dischtime < '2025-12-31' GROUP BY p.gender, medication_complexity_score ORDER BY p.gender, medication_complexity_score NULLS LAST;